contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        uint256 balBefore = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            (reverted &&
                c.balanceOf(msg.sender) == balBefore &&
                c.totalSupply() == supplyBefore &&
                c.totalDistributed() == distributedBefore) ||
            (!reverted &&
                amount <= balBefore &&
                c.balanceOf(msg.sender) == balBefore - amount &&
                c.totalSupply() == supplyBefore - amount &&
                c.totalDistributed() == distributedBefore - amount)
        );
    }

    receive() external payable {}
}

