pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        uint256 balBefore;
        try c.balanceOf(msg.sender) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 distributedBefore;
        try c.totalDistributed() returns (uint256 __r) { distributedBefore = __r; } catch { return; }
        bool reverted;
        try c.burn(amount) { reverted = false; } catch { reverted = true; }
        assertTrue((reverted &&
                c.balanceOf(msg.sender) == balBefore &&
                c.totalSupply() == supplyBefore &&
                c.totalDistributed() == distributedBefore) ||
            (!reverted &&
                amount <= balBefore &&
                c.balanceOf(msg.sender) == balBefore - amount &&
                c.totalSupply() == supplyBefore - amount &&
                c.totalDistributed() == distributedBefore - amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
